const { validationResult, query } = require('express-validator');

const app = express();
const isProduction = process.env.NODE_ENV === 'production';

// 1. SECURITY: Add security headers with helmet
app.use(helmet());

// 2. SECURITY: Limit JSON body size to prevent DoS attacks
app.use(express.json({ limit: '10kb' }));

// 3. SECURITY: Add rate limiting to prevent brute force/DoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api', limiter);

// Health endpoint (no authentication needed)
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint with input validation
app.get('/users', [
  // Input validation: validate and sanitize query parameters
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be an integer between 1 and 100')
    .toInt(),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer')
    .toInt(),
], (req, res) => {
  // Check validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const { limit = 10, offset = 0 } = req.query;

  // Sample data (in real app, this would come from a database)
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Slice based on validated parameters
  const paginatedUsers = users.slice(Number(offset), Number(offset) + Number(limit));

  res.json({ users: paginatedUsers, total: users.length });
});

// 4. SECURITY: 404 handler for unknown routes
app.use((req, res, next) => {
  res.status(404).json({ error: 'Not found' });
});

// 5. SECURITY: Global error handling middleware
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  console.error('Error:', err.message);

  // In production, don't leak stack traces
  const message = isProduction ? 'Internal server error' : err.message;
  const status = err.status || 500;

  res.status(status).json({
    error: message,
    ...(isProduction === false && { stack: err.stack }), // Only show stack in dev
  });
});

const PORT = process.env.PORT || 3000;

// 6. SECURITY: HTTPS redirect in production (should be handled by reverse proxy in real deployments)
if (isProduction) {
  app.enable('trust proxy');
  app.use((req, res, next) => {
    if (req.secure) {
      next();
    } else {
      res.redirect(`https://${req.hostname}${req.url}`);
    }
  });
}

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${isProduction ? 'production' : 'development'} mode`);
});

module.exports = app;

