app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', validateUserQuery, (req, res) => {
  // 5. INPUT VALIDATION: Check validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const limit = parseInt(req.query.limit) || 10;
  const offset = parseInt(req.query.offset) || 0;

  // In real app, these would come from a database with limit/offset applied
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  res.json({
    data: users.slice(offset, offset + limit),
    meta: { limit, offset, total: users.length }
  });
});

// 6. ERROR HANDLING: 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// 7. ERROR HANDLING: Global error handler (prevent stack trace leaks)
app.use((err, req, res, next) => {
  console.error('Error:', err.message);

  // In production, don't leak stack traces
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(err.status || 500).json({ 
    error: message 
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
